import argparse
from .core import archive_dataset


# %% ../nbs/01_cli.ipynb 3
def build_cli():
    "Create CLI entry point for dataset archival"
    # import argparse

    parser = argparse.ArgumentParser(description="Archive dataset to WebDAV with metadata and verification.")
    parser.add_argument("--source", required=True, help="Path to the dataset folder")
    parser.add_argument("--label", required=True, help="Dataset label (e.g. 2025_exp01)")
    parser.add_argument("--title", required=True, help="Dataset title")
    parser.add_argument("--source_name", required=True, help="Who collected the data")
    parser.add_argument("--date_collected", required=True, help="Date the data was collected")
    parser.add_argument("--description", required=True, help="Short dataset description")
    parser.add_argument("--responsible", required=True, help="Person responsible for the dataset")
    parser.add_argument("--username", required=True, help="WebDAV username (e.g. a012197)")
    parser.add_argument("--email", required=True, help="Contact email")
    parser.add_argument("--webdav", default="https://u-drive.unipi.it/remote.php/webdav/", help="Base WebDAV URL")
    parser.add_argument("--registry", default="upload_registry.csv", help="Local CSV registry path")
    parser.add_argument("--remote_registry", default="https://u-drive.unipi.it/remote.php/webdav/RRL/archival_data/_registry/upload_registry.csv", help="Shared remote registry path")
    parser.add_argument("--merged_registry", default="upload_registry_merged.csv", help="Merged registry backup path")
    parser.add_argument("--dry-run", action="store_true", help="Preview actions without uploading")
    parser.add_argument("--verify", action="store_true", help="Verify uploaded files")
    parser.add_argument("--strict", action="store_true", help="Fail if verification mismatches")
    parser.add_argument("--no-sync-registry", action="store_true", help="Do not sync the registry after upload")

    return parser

def main():
    # from dataset_archiver.core import archive_dataset

    parser = build_cli()
    args = parser.parse_args()

    metadata = {
        "title": args.title,
        "source": args.source_name,
        "date_collected": args.date_collected,
        "description": args.description,
        "responsible": args.responsible
    }

    archive_dataset(
        source_folder=args.source,
        base_webdav_url=args.webdav,
        label=args.label,
        metadata=metadata,
        username=args.username,
        contact_email=args.email,
        registry_path=args.registry,
        remote_registry_url=args.remote_registry,
        merged_local_backup_path=args.merged_registry,
        verify=args.verify,
        strict=args.strict,
        sync_registry=not args.no_sync_registry,
        dry_run=args.dry_run
    )

